INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (15, 5, 'theory', 'Routing: Tables, ARP, ICMP, and Traceroute');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 0, 'The table has entries 10.0.0.0/8 → R1, 10.1.0.0/16 → R2, and 0.0.0.0/0 → R3. Where will a packet for 10.1.2.3 go?', '["To R2", "To R1", "To R3", "It will be dropped"]', 0, 'The /8, the /16, and the default route all match; the longest prefix wins, which is /16.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 1, 'What changes in a packet as it passes through a router?', '["The source and destination addresses", "TTL decreases by one (and the header checksum is recomputed)", "Nothing changes", "The port number"]', 1, 'The link-layer header changes too, but the IP addresses stay; TTL is one less.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 2, 'What is ARP for?', '["To find an IP address from a name", "To report a routing error", "To find the MAC address of the next hop from its IP address", "To build the routing table"]', 2, 'An ARP request is a broadcast; the reply goes to the single sender and is saved in the ARP cache.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 3, 'How does traceroute learn the addresses of the routers on the path?', '["It reads their tables over the network", "It uses a special tracing protocol in every router", "It asks the provider", "It sends packets with TTL 1, 2, 3… and reads the addresses from ICMP time exceeded"]', 3, 'Every router where TTL reaches zero sends the sender an ICMP time exceeded with its own address.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (15, 5, 4, 'A ping to a remote server reaches it, but no reply comes back. What is the most likely cause?', '["The server has no return route to your network", "The packet''s TTL is too large", "The destination address is private", "The ARP cache is full"]', 0, 'The reply is a packet too: if there is no entry for your subnet on the way back, it gets lost.');
